/* Review 8: explicit prize scope, evidence inventory and spectral diagnostics. */
(() => {
  'use strict';
  const old = window.ResearchObservatory, D = window.OBSERVATORY_MILLENNIUM;
  if (!old || !D) return;
  const H=window.OBSERVATORY_HUB;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const link=(route,label)=>`<a href="#research/${esc(route)}">${esc(label)}</a>`;
  const eq=s=>`<div class="hub-eq">${esc(s)}</div>`;
  const panel=(title,body)=>`<section class="hub-panel"><h2>${esc(title)}</h2>${body}</section>`;
  const table=(heads,rows)=>`<div class="hub-table-wrap"><table class="hub-table"><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const list=rows=>`<ul>${rows.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
  const badge=(s,kind='conditional')=>`<span class="hub-badge ${esc(kind)}">${esc(s)}</span>`;
  const doc=(name,label)=>D.documents?.[name]?`<button data-r-doc="round8/${esc(name)}">${esc(label)}</button>`:'';
  const src=id=>{const s=D.sources.find(s=>s.id===id);return s?`<a href="${window.ResearchHub.safeURL(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.short||s.title)}</a>`:'';};
  const action=(r,s)=>`<div class="hub-actions">${link(r,s)}</div>`;
  const routes={home:'Research home',millennium:'The $1M problem','gap-lab':'Finite-size experiment','spectral-bound':'Spectral proof & experiment','scalar-response':'Scalar response','review8':'Current audit','roadmap8':'Bidirectional roadmap','sources8':'Primary sources'};
  const nav=p=>`<nav class="hub-nav" aria-label="Research review navigation">${Object.entries(routes).map(([r,s])=>`<a href="#research${r==='home'?'':'/'+r}" ${p===r?'aria-current="page"':''}>${esc(s)}</a>`).join('')}</nav>`;
  const header=(title,desc)=>`<header class="hub-header"><div><p class="hub-kicker">Physics Observatory · Review 8</p><h1>${esc(title)}</h1><p class="hub-deck">${esc(desc)}</p></div></header>`;
  const footer=()=>`<footer class="hub-foot">Checked ${esc(D.date)}. Agent critique is not human peer review or proof-assistant certification. ${link('sources8','Source provenance')} · <a href="/research-round8.zip" download>Download this review and runnable evidence</a> · ${link('history','Earlier research home')} · <a href="#study">Learning atlas</a></footer>`;
  let inventoryQuery='',inventoryFilter='';
  const extensions=[
    {id:'R8-R',title:'Scalar response under momentum-grid refinement',route:'scalar-response',kind:'check',summary:'A new fixed-domain delayed-source experiment checks field, potential and scalar responses independently of perturbation-size refinement. The coarse grid misses the declared working scale.',verification:'Field response changes by 2.87e−4 from 64 to 128 nodes and 1.39e−6 from 128 to 256, below the declared 2e−5 scale.',limit:'Adjacent-grid evidence at fixed physical cutoffs and finite difference step; no rigorous total-error bound or continuum claim.'},
    {id:'R7-F',title:'Dynamical scalar and finite quantum modes',route:'finite',kind:'proof',summary:'An action-derived scalar supplies its own force and energy. Its exchange cancels the field’s exchange, giving a finite-model work identity and a conditional continuation result.',verification:'Historical review: 42 critic and 47 implementation gates. The current audit below rechecks a specified subset and repairs new interface defects.',limit:'Fixed magnetic field, finite regulator and polynomial gauge coefficient. It has no evolved quantum directional stress.'},
    {id:'R7-G',title:'Scalar, electromagnetic stress and expanding geometry',route:'gravity',kind:'check',summary:'A separate classical Bianchi I system evolves two expansion rates, a scalar and aligned electric and magnetic fields. Its Einstein constraint propagates when total matter exchange vanishes.',verification:'Eight historical finite-time cases, analytic fixtures and a missing-force control; new audit status is recorded separately.',limit:'No quantum Dirac sector. The exponential gauge function differs from the finite quantum model; these are separate systems.'},
    {id:'R7-C',title:'Reference subtraction and bounded-scalar obstruction',route:'cutoff',kind:'proof',summary:'An exact continuous coefficient can be kept positive with regulator-dependent reference subtraction. A uniformly bounded added field cannot cancel the specified joint-cutoff divergence.',verification:'Algebra and conditional proof routes are archived; the actual regulator and coefficient hypotheses remain required.',limit:'Positivity of one coefficient neither renormalizes the complete current/stress nor removes the physical Landau-pole question.'},
    {id:'R8-F',title:'Finite positive energies can vanish in the limit',route:'gap-lab',kind:'check',summary:'The lowest nonzero massless lattice frequency converges at fixed box size and then vanishes as the box grows. This supplies a counterexample to an invalid inference used in gap hunting.',verification:'New analytic fixture, computed refinement tables and independent arithmetic checks. See the recorded diagnostic report.',limit:'A free scalar diagnostic with its zero mode explicitly excluded; it is not a Yang–Mills simulation.'},
    {id:'R8-S',title:'A mass plateau is an upper bound on spectral onset',route:'spectral-bound',kind:'proof',summary:'For a positive Laplace spectral measure, effective mass decreases and stays above the lowest mass to which that observable couples. A tiny lighter-state overlap can hide behind an early plateau.',verification:'Conventional inequality proof plus a stable two-state calculation and independent numerical checks.',limit:'This does not establish spectral positivity or any uniform gap estimate for four-dimensional Yang–Mills.'}
  ];
  function inventory(){const items=[...H.claims.map(c=>({...c,route:'solution/'+c.id})),...extensions];const q=inventoryQuery.trim().toLowerCase();const filtered=items.filter(c=>(!inventoryFilter||c.kind===inventoryFilter)&&(!q||[c.id,c.title,c.summary,c.limit].join(' ').toLowerCase().includes(q)));return `<p class="hub-meta" role="status">${filtered.length} of ${items.length} result summaries. Each link opens assumptions, equations, objections and evidence.</p>`+(filtered.length?filtered.map(c=>`<article class="m8-result"><div><span class="hub-id">${esc(c.id)}</span> ${badge(c.kind==='proof'?'Conditional mathematical result':c.kind==='check'?'Numerical result':c.status||c.kind,c.kind)}<h3>${link(c.route,c.title)}</h3></div><div><p>${esc(c.summary)}</p><p><strong>Evidence:</strong> ${esc(c.verification)}</p><p class="hub-meta"><strong>Boundary:</strong> ${esc(c.limit)}</p></div></article>`).join(''):'<p class="hub-empty">No matching results. Clear the search or choose all evidence types.</p>');}
  function home(){return header('What holds. What failed. What comes next.','A complete research ledger linking the finite Einstein–QED studies to a precise new question: which evidence could establish a continuum quantum mass gap?')+
    `<div class="m8-overview"><section class="hub-panel"><div class="hub-badges">${badge('$1,000,000 Millennium Prize','open')}${badge('Officially unsolved','open')}</div><h2>Yang–Mills existence and mass gap</h2><p>Construct a nontrivial four-dimensional quantum Yang–Mills theory for each compact simple gauge group, with a strictly positive energy gap above its vacuum. ${src('clay-target')} · ${src('clay-prize')}</p><p>This is the closest related prize problem by mathematical subject. The connection is gauge theory and continuum control. Our abelian finite-mode work does not yet provide the nonabelian construction or gap estimate.</p>${action('millennium','Read the exact target and relation')}</section><section class="hub-panel"><h2>Current scientific status</h2>${table(['Question','Decision'],[
      ['Finite-model conservation and continuation','Restricted results retained; current audit repairs are documented.'],
      ['Common Einstein–QED quantum stress','Open. Current and both pressures still need one consistent causal prescription.'],
      ['Joint-cutoff and physical matching','Open beyond the stated coefficient lemmas.'],
      ['Yang–Mills existence and mass gap','Open. No certificate in this project establishes it.']])}<div class="hub-actions">${link('review8','Read this audit')}${link('roadmap8','Inspect the next obligations')}</div></section></div>`+
    panel('New work that changes the inference',`<div class="hub-grid"><article><h3>${link('gap-lab','A converged finite box can still mislead')}</h3><p>Resolving the mesh at fixed volume can produce an apparently stable positive energy. The same massless model loses that energy scale as the volume grows. The two limits answer different questions.</p></article><article><h3>${link('spectral-bound','A convincing plateau can hide a lighter state')}</h3><p>A positive correlator with a tiny low-energy overlap looks massive at early times. Its effective mass is an upper bound on the lowest supported energy. A plateau cannot certify a positive lower bound.</p></article></div><p>These are new project calculations of known mathematical mechanisms. They are tests of proposed inference rules, with no claim of a new discovery in Yang–Mills theory.</p>`)+
    panel('Every result, with its strongest boundary',`<div class="hub-filter"><label>Search the results<input id="m8-search" type="search" value="${esc(inventoryQuery)}" placeholder="Scalar, cutoff, energy, tangent…"></label><label>Evidence type<select id="m8-filter"><option value="">All evidence types</option><option value="proof" ${inventoryFilter==='proof'?'selected':''}>Conditional mathematical results</option><option value="check" ${inventoryFilter==='check'?'selected':''}>Numerical results</option><option value="rejected" ${inventoryFilter==='rejected'?'selected':''}>Rejected inferences</option></select></label></div><div id="m8-results">${inventory()}</div>`)+
    panel('The full project remains connected',table(['Work area','What it contains','Where to continue'],[
      ['Foundations and learning','Mechanics, mathematics, quantum theory, relativity, sound, geometry, astronomy and astrophysics.','<a href="#study">Learning home</a> · <a href="#explore">Specialist rooms</a>'],
      ['Historical and patent studies','Tesla catalogue, Newton records, magnetism and unusual claims with evidence boundaries.','<a href="#patents/dossiers">Patent Research Room</a>'],
      ['Original four research fronts','WGC/Festina Lente, curved-space pair creation, inner-horizon dynamics and photon–graviton mixing.',link('evidence','Four open frontiers')],
      ['Finite quantum response','Electric-field reversal, response differentiation, finite regulator and counterexamples.',link('solutions','Original 11 result pages')],
      ['Scalar and gravity extensions','Action-derived variables, energy exchange, separate metric evolution and proof routes.',link('variables','Review 7 overview')],
      ['Verification and reproducibility','Claim records, raw data, historical failures, primary-source ledgers and advisor guidance.',link('review8','Current review')+' · '+link('sources','Historical sources')]
    ]))+panel('How to use this research home',`<ol><li>Choose a result and read its model and assumptions before its numerical value.</li><li>Open its skeptical objection and verification record. Historical checks and new reruns have separate labels.</li><li>Download the plotted CSV and runnable review to reproduce the same calculation.</li><li>Use the bidirectional roadmap to find the next missing premise. A missing premise stays open until it is derived and checked.</li></ol>`);}
  function millennium(){return header('The related million-dollar problem','Yang–Mills existence and mass gap is the closest Millennium problem to the project’s gauge-field and regulator questions.')+
    panel('Exact target and official status',`<p>Clay lists this problem as unsolved and allocates $1 million to its solution. ${src('clay-target')} · ${src('clay-prize')}</p><p>For every compact simple gauge group G, construct a nontrivial quantum Yang–Mills theory on ℝ⁴ under a rigorous axiomatic framework and establish a positive mass gap. ${src('clay-statement')}</p>${eq('G compact and simple; example G=SU(2) or SU(3)\nAμ=AμᵃTᵃ;  [Tᵃ,Tᵇ]=i fᵃᵇᶜTᶜ;  Tr(TᵃTᵇ)=δᵃᵇ/2\nFμν=∂μAν−∂νAμ−ig[Aμ,Aν]\nSE=½∫d⁴x Tr(FμνFμν)  (g inside F)\nHΩ=0;  spec(H) ⊂ {0} ∪ [Δ,∞),  Δ>0')}
    <p>The action is a formal starting point, not the construction. The gap is in the physical quantum spectrum after the required limits. A fixed gauge potential, classical oscillation frequency or added bare mass does not establish it.</p>`)+
    panel('What connects to our work—and which steps are absent',table(['Our result','Valid connection','Unproved implication'],[
      ['U(1) Maxwell–Dirac dynamics','Covariant fields, quantum matter, regulators and response.','U(1) has no nonabelian commutator; it is not a compact simple group in the prize statement.'],
      ['Positive finite Maxwell coefficient Z','An equation avoids a singular denominator in its stated finite domain.','No inference to the lowest physical eigenvalue of an infinite-dimensional nonabelian Hamiltonian.'],
      ['Work identity and Einstein constraint','Local conservation is an essential consistency requirement.','Conservation does not construct the continuum quantum theory or bound its spectrum.'],
      ['Regulator-dependent subtraction','Makes a concrete coefficient question explicit.','The renormalized state, all relevant observables and physical matching still require control.'],
      ['New scalar field','A legitimate different theory when its action and stress are specified.','A Higgs, Proca or scalar mass scale does not solve pure Yang–Mills by insertion.']
    ]))+panel('The Landau-pole analogy has opposite perturbative running',eq('One charged Dirac species in QED, above its mass threshold:\nμ de/dμ = +e³/(12π²) + O(e⁵)\nPure nonabelian Yang–Mills:\nμ dg/dμ = −[11 CA/(3·16π²)]g³ + O(g⁵)\nSU(N): CA=N')+`<p>The pure Yang–Mills coupling weakens at high energy. Strong infrared dynamics motivates the mass-gap question, but perturbative running alone cannot prove that gap. The finite Landau-level cutoff in our solver and the formal QED Landau pole are distinct objects. ${src('gross')}</p>`)+
    panel('Useful progress in the literature, with its exact limit',table(['Source','Established or computed result','Remaining separation'],[
      [src('strong'),'Infinite-volume lattice correlation decay under an explicit strong-coupling condition for SO(N) and SU(N).','Its fixed-lattice strong-coupling regime does not establish the weak-coupling four-dimensional continuum limit.'],
      [src('glueball'),'Numerical glueball spectra with continuum extrapolations for SU(N) gauge theories.','Numerical evidence and extrapolation assumptions do not supply an all-regulator rigorous lower bound.'],
      [src('stochastic'),'Renormalized stochastic Yang–Mills dynamics in two and three dimensions at finite volume.','Different dimension and construction target from the four-dimensional Millennium problem.']
    ]))+panel('Other Millennium problems',`<p>Navier–Stokes existence and smoothness is related through nonlinear PDE estimates and continuation arguments; it is less directly connected to the gauge-field spectral question. Riemann, Hodge, Birch–Swinnerton-Dyer and P versus NP have no specific theorem-level bridge established by the current project. Poincaré is the solved Millennium problem. ${src('clay-prize')}</p><div class="hub-actions">${link('roadmap8','Open the two-direction proof plan')}${link('gap-lab','Test the finite-size shortcut')}</div>`);}
  function plot(key){const p=D.plots?.[key];if(!p||!Array.isArray(p.series)||!p.series.length||!p.series.every(s=>s&&Array.isArray(s.points)&&s.points.length&&s.points.every(v=>Array.isArray(v)&&v.length===2&&v.every(Number.isFinite))))return '<p class="hub-empty" role="status">No valid recorded data are available for this plot.</p>';return old.chart(p.series,{title:p.title,xLabel:p.xLabel,yLabel:p.yLabel,zero:false})+`<p class="hub-plot-caption">${esc(p.caption)}</p><a href="${window.ResearchHub.safeURL(p.csv)}" download>Download the plotted CSV</a>`;}
  function gapLab(){return header('A finite positive frequency is not a mass gap','An exact free-field counterexample separates mesh refinement from increasing the physical volume.')+
    panel('Model, observable and boundary condition',eq('Periodic lattice: N≥3 sites, spacing a>0, L=Na, m≥0\nωk²=m²+(4/a²)sin²(πk/N), k=0,…,N−1\nLowest nonzero momentum frequency: ω1\nm=0: ω1=(2/a)sin(π/N)>0 at finite N,L\nAt fixed L: lim a→0 ω1=2π/L\nThen lim L→∞ 2π/L=0')+`<p>The homogeneous k=0 mode is excluded from this diagnostic. Its exclusion is explicit because the full massless model is not being certified as gapped. The plotted quantity is the lowest <em>nonzero momentum</em> frequency, not the full theory’s mass gap. A nonzero mass m gives a separate control with infinite-volume frequency tending to m.</p>`)+
    panel('First limit: resolve the same physical box',plot('mesh'))+
    panel('Second limit: increase the physical box',plot('volume'))+
    panel('Skeptic verdict and mathematical proof',`<p>For 0&lt;z≤π/3, sin(z)&gt;0 and sin(z)/z→1 as z→0. Substituting z=π/N with a=L/N proves the fixed-volume limit. Taking L→∞ then proves the loss of any common positive lower bound. No numerical fitting is required for this conclusion.</p><p>A finite sequence of computed positive energies cannot reverse these quantifiers:</p>${eq('For every finite regulator r, there exists Δr>0\nDOES NOT IMPLY\nThere exists Δ*>0 such that every sufficiently fine / large r obeys Δr≥Δ*.')}<p>This does not disprove a Yang–Mills gap. It disproves a proposed inference from finite positivity alone. The experiment’s exact formula supplies an independent reference for the code and its plots.</p><div class="hub-actions">${doc('diagnostics.md','Read parameters, independent checks and all edge cases')}${link('spectral-bound','Test the apparent-plateau shortcut')}</div>`);}
  function spectral(){return header('What a mass plateau can actually prove','A positive spectral correlator supplies an upper bound on its lowest supported energy. A rigorous lower bound requires additional information.')+
    panel('A precise conditional lemma',eq('C(t)=∫[0,∞) e^(−Et) dμ(E), μ≥0, μ≠0\nC(t), C(t+δ) finite and positive; δ>0; m*=inf supp μ\nmeff(t;δ)=[log C(t)−log C(t+δ)]/δ\nmeff(t;δ)≥m*;  meff(t;δ) is nonincreasing in t')+`<p>For quantum-field applications, use vacuum-subtracted smeared operators giving finite-norm states; coincident unsmeared local fields can be singular. Assume the positive Laplace representation on the stated time interval. Divide C(t+δ) by C(t): it is the average of exp(−Eδ) under the probability measure proportional to exp(−Et)dμ. Since E≥m*, that average is at most exp(−m*δ). Taking the logarithm proves the bound in the displayed direction.</p><p>Hölder’s inequality makes log C convex. Forward slopes of a convex function are nondecreasing, so their negatives—the effective masses—are nonincreasing. In a finite positive sum, equality at a single common mass is exact. A noisy fitted value does not automatically obey this exact bound. A general signed correlator or finite-temperature cosh expression requires a different argument.</p>`)+
    panel('A light state hidden behind a plateau',plot('plateau')+`<p>The data are generated from a stated two-exponential toy correlator, not measured Yang–Mills configurations. The tiny lighter-state overlap makes early times resemble the heavier mass. Late times expose the true spectral onset. Stable log-sum-exp evaluation avoids manufacturing a plateau through underflow.</p>`)+
    panel('What would instead certify a lower bound?',eq('Conditional sufficient route, fixed physical units:\nCᵃ,ᴸ_O(t) → C_O(t) for each t≥0\n0≤Cᵃ,ᴸ_O(t)≤A_O exp(−Δ*t), uniformly in regulators\nA_O<∞ independent of a,L; Δ*>0 common\nPositive spectral representation survives the limit\n⇒ supp μ_O ⊂ [Δ*,∞)')+`<p>If μ_O has positive weight below Δ*, then some E₀&lt;Δ* contains a positive amount c of that weight. The correlator obeys C_O(t)≥c exp(−E₀t), contradicting the upper bound as t→∞. This is a conventional proof of the conditional implication.</p><p>To conclude a <em>Hamiltonian</em> gap, the estimate must cover a family whose vacuum-subtracted states OΩ span a dense subspace orthogonal to the vacuum, with a common Δ*. A single observable can fail to couple to lighter states. Quantum-field existence, reconstruction, nontriviality and the necessary uniform estimates are all still open for the prize target.</p><div class="hub-actions">${doc('advisor.md','Read the independent advisor derivation')}${link('roadmap8','Inspect missing premises and search traces')}</div>`)+
    panel('Skeptical acceptance conditions',list(['Positive spectral weights and vacuum subtraction must be established, not inferred from a convenient fit.','The zero-temperature transfer interpretation does not automatically extend to a thermal periodic correlator.','A low-noise fit can miss an exactly absent or extremely small overlap.','Uniform estimates need a fixed physical normalization; rescaling time or the bare coupling changes their meaning.','The claim is conditional mathematics. Numerical checks test the implementation, not the unresolved Yang–Mills premises.']));}
  function scalarResponse(){const r=D.response;const fmt=x=>Number(x).toExponential(5);return header('A finer grid changes the response verdict','The finite scalar model now has a separate response-grid check. Changing the finite-difference step and changing the momentum quadrature answer different questions.')+
    panel('Physical model and frozen preparation',`<p>This uses the existing finite Maxwell–Dirac model with its dynamical scalar, fixed magnetic field and action-derived exchange terms. It differentiates a delayed source about a nonzero probe amplitude; the same source is present in both perturbed runs.</p>${eq('b=10; K=20; n=0,1 retained; g=0.1; ν=0.5\na(0)=0; φ(0)=0.4; y(0)=0.1; vacuum quantum modes\npump duration=4; final time=6; 121 sampled times\nprobe starts at 4.5, duration=1, central amplitude λ=0.15\nε=5×10⁻⁵; Rq(s)=[q(s;λ+ε)−q(s;λ−ε)]/(2ε)\nq ∈ {a,x,φ,y}; nK ∈ {64,128,256}\nrtol=2×10⁻¹⁰; atol=2×10⁻¹²; maximum time step=0.05')}${action('finite','Read the complete finite-model equations')}`)+
    panel('Recorded response histories',plot('response'))+
    panel('Compare each response, not only the base field',table(['Nodes','Potential response','Field response','Scalar response','Scalar-velocity response'],r.comparisons.map(c=>[`${c.coarse_nK} → ${c.fine_nK}`, ...['a','x','phi','y'].map(k=>fmt(c.max_abs_response_difference[k]))]))+`<p>Entries are the maximum absolute difference over common sampled times. The predeclared working threshold is <strong>2×10⁻⁵</strong> in these dimensionless response units. The first pair fails; the second meets it for every listed response. All 90 pre-probe samples are zero in every computed response.</p>`)+
    panel('Skeptic verdict and remaining test',`<p>The old small-ε agreement did not establish momentum convergence. This experiment resolves that specific uncertainty to a declared working scale. The 128→256 field discrepancy is 1.38903×10⁻⁶; it is a measured adjacent-grid difference, not a certified upper bound on the total error.</p>${list(r.limitations)}<p>Scalar histories are checked separately because a well-resolved base electric field does not guarantee a well-resolved derivative or scalar response. This experiment keeps the momentum window and Landau cutoff fixed; it supplies no current/stress continuum limit.</p><div class="hub-actions">${doc('code-audit.md','Read the skeptical review')}<a href="/research-round8.zip" download>Download the exact response script and histories</a>${link('roadmap8','Next quantum-stress obligation')}</div>`);}
  function review(){return header('The current skeptical audit','Review 8 preserves the delivered versions, tests specific failures and separates rerun evidence from historical reports.')+
    panel('Coverage and reproducibility',`<p>${esc(D.audit.scope)}</p>${table(['Layer','Executed status','Scope'],D.audit.layers.map(r=>r.map(esc)))}<p>Line-by-line review records a reviewer’s inspected scope. It is not exhaustive branch coverage. No claim is made that every historical file, third-party package or theorem has been fully verified.</p>`)+
    panel('Confirmed findings and responses',D.audit.findings.map(f=>`<article class="hub-card">${badge(f.status,f.status==='Fixed'?'check':'open')}<h3>${esc(f.title)}</h3><p><strong>Failure:</strong> ${esc(f.failure)}</p><p><strong>Impact:</strong> ${esc(f.impact)}</p><p><strong>Correction:</strong> ${esc(f.fix)}</p><p><strong>Test:</strong> ${esc(f.test)}</p></article>`).join(''))+
    panel('What the new checks establish',`<p>${esc(D.audit.verdict)}</p><div class="hub-actions">${doc('code-audit.md','Read the complete scientific code audit')}${doc('diagnostics.md','Read the new experiment diagnostics')}<a href="/research-round8.zip" download>Download original hashes, revised code and tests</a></div>`)+
    panel('Historical evidence remains inspectable',`<p>The earlier site contains 11 focused result pages, scalar and gravity pages, 44 theory nodes, original numerical histories and review documents. Their reported counts describe those historical runs. This page records the new execution scope so that an old success is not silently counted as a new rerun.</p><div class="hub-actions">${link('audit','Review 6 code findings')}${link('variables','Review 7 evidence')}${link('solution/R5-P1','Earlier proof-search audit')}</div>`);}
  function roadmap(){return header('Bidirectional reasoning with an honest stopping point','Work forward from checked premises and backward from a precise target. An unsupported meeting point remains an open obligation.')+
    panel('Forward and backward meet for a restricted lemma',table(['Step','Forward evidence','Backward requirement'],[
      ['1','Positive spectral measure with finite Laplace transform.','An effective-mass statement requires a defined observable and positive C.'],
      ['2','Normalize e^(−Et)dμ by C(t).','An upper bound on C(t+δ)/C(t) is sufficient.'],
      ['3','E≥inf supp μ gives exp(−Eδ)≤exp(−m*δ).','Taking a negative logarithm gives meff≥m*.'],
      ['4','Hölder supplies convexity of log C.','Monotonicity follows from ordered secant slopes.'],
      ['5','Independent numerical fixtures challenge implementation.','Fixtures do not replace either mathematical premise.']
    ])+`<p>This is a conventional derivation under declared premises. The executable planner replays only admitted rules; it cannot prove those rules or make missing physical assumptions true.</p><div class="hub-actions">${doc('proof-route.md','Read the frozen proof contract and search result')}<a href="/millennium-proof-map.json" download>Download proof routes and missing obligations</a></div>`)+
    panel('Backward from the actual prize: where the route stops',table(['Required target','Needed premise','Current state'],[
      ['A four-dimensional physical Hilbert space and Hamiltonian','Rigorous nontrivial Yang–Mills Schwinger functions and reconstruction conditions.','Open for the prize target. No finite ODE supplies this.'],
      ['A positive physical energy gap','Uniform exponential decay with a common physical mass on a dense family of states.','Open. A finite box or one fitted channel is insufficient.'],
      ['A continuum theory','Control of regulator removal with fixed physical matching and admissible limits.','Open. Strong-coupling fixed-lattice estimates do not cover it automatically.'],
      ['The full group requirement','A proof addressing each compact simple G or a valid general construction.','Studying SU(2) is a bounded starting point, not the entire statement.']
    ])+`<p>There is no complete route from our finite-model facts to this target. In the stored search library the prize goal remains underivable. That means the supplied library has no certificate, not that the mathematical problem is impossible.</p>`)+
    panel('Advisor experiment queue',D.experiments.map(e=>`<article class="hub-card">${badge(e.status,e.status==='Executed'?'check':'open')}<h3>${esc(e.title)}</h3><p><strong>Hypothesis:</strong> ${esc(e.hypothesis)}</p><p><strong>Next calculation:</strong> ${esc(e.method)}</p><p><strong>Reject or stop if:</strong> ${esc(e.reject)}</p><p><strong>What it could establish:</strong> ${esc(e.scope)}</p></article>`).join(''))+
    panel('Keep the Einstein–QED branch moving',`<p>The existing next bridge remains useful: compute the current, quantum energy and both directional pressures from one causal state and one renormalization prescription in a prescribed smooth axial geometry. Test the force Ward identity from independently obtained quantities, then assess whether self-consistent metric evolution is justified. A pressure defined by the identity being tested would make that test circular.</p><p>The mass-gap branch adds lessons about physical scale, regulator order and spectral estimates. It does not justify splicing two different reduced actions into a completed theory.</p>${action('proofs','Inspect the existing 17-step and 11-step routes')}`);}
  function sources(){return header('Primary sources and reading depth','Official status, exact research statements and project computations have separate provenance.')+panel('External sources',D.sources.map(s=>`<article class="hub-source"><h3><a href="${window.ResearchHub.safeURL(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></h3><p>${esc(s.authors)} · ${esc(s.date)}</p><p><strong>Used for:</strong> ${esc(s.use)}</p><p class="hub-meta"><strong>Reading depth:</strong> ${esc(s.depth)}. ${esc(s.limit)}</p></article>`).join(''))+panel('Project evidence',`<p>The previous source and data files were recovered from the existing Observatory’s delivered archive. The new diagnostic code, exact toy models, review notes and content are project-generated. No claim of an exhaustive literature search or literature novelty is made.</p><div class="hub-actions">${link('sources','Historical source ledger')}<a href="/research-round8.zip" download>Download this review</a></div>`);}
  for(const [name,body] of Object.entries(D.documents||{}))window.OBSERVATORY_RESEARCH.documents['round8/'+name]=body;
  function render(page='home'){if(page==='history')return old.render('home');if(!Object.hasOwn(routes,page))return old.render(page);const f={home,millennium,'gap-lab':gapLab,'spectral-bound':spectral,'scalar-response':scalarResponse,'review8':review,'roadmap8':roadmap,'sources8':sources}[page];return `<div class="research-shell hub m8">${nav(page)}${f()}${footer()}</div>`;}
  function afterRender(){const p=location.hash.split('/')[1]||'home';if(Object.hasOwn(routes,p))document.title=routes[p]+' · Physics Observatory';else old.afterRender();}
  document.addEventListener('input',e=>{if(e.target.id==='m8-search'){inventoryQuery=e.target.value;const node=document.querySelector('#m8-results');if(node)node.innerHTML=inventory();}});
  document.addEventListener('change',e=>{if(e.target.id==='m8-filter'){inventoryFilter=['','proof','check','rejected'].includes(e.target.value)?e.target.value:'';const node=document.querySelector('#m8-results');if(node)node.innerHTML=inventory();}});
  window.ResearchMillennium={render,plot,inventory};
  window.ResearchObservatory={...old,render,afterRender};
})();
